def positivePartitionValues (x : E) : Set ℝ :=
  {z | ∃ (n : ℕ) (u : Fin n → E), (∀ i, 0 ≤ u i) ∧ (∑ i, u i) ≤ x ∧
    z = ∑ i, ‖u i‖}

